    79	   * For each expert, each thread processes the tokens of the corresponding
    80	   * blocks and stores the corresponding expert_id for each block.
    81	   */
    82	  if (threadIdx.x < num_experts) {
    83	    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1];
    84	         i += block_size) {
    85	      expert_ids[i / block_size] = threadIdx.x;
    86	    }
    87	  }
    88	
    89	  /**
    90	   * Each thread processes a token shard, calculating the index of each token
    91	   * after sorting by expert number. Given the example topk_ids =
    92	   * [0,1,2,1,2,3,0,3,4] and block_size = 4, then the output would be [0, 6, *,
    93	   * *, 1, 3, *, *, 2, 4, *, *, 5, 7, *, *, 8, *, *, *], where * represents a
    94	   * padding value(preset in python).
    95	   */
    96	  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
    97	    int32_t expert_id = topk_ids[i];
    98	    /** The cumsum[expert_id] stores the starting index of the tokens that the
    99	     * expert with expert_id needs to process, and
   100	     * tokens_cnts[threadIdx.x][expert_id] stores the indices of the tokens
   101	     * processed by the expert with expert_id within the current thread's token
   102	     * shard.
   103	     */
   104	    int32_t rank_post_pad =
   105	        tokens_cnts[index(num_experts, threadIdx.x, expert_id)] +
   106	        cumsum[expert_id];
