   116	template <typename scalar_t>
   117	__global__ void moe_align_block_size_global_mem_kernel(
   118	    scalar_t* __restrict__ topk_ids, int32_t* sorted_token_ids,
   119	    int32_t* expert_ids, int32_t* total_tokens_post_pad, int32_t num_experts,
   120	    int32_t block_size, size_t numel, int32_t* tokens_cnts, int32_t* cumsum) {
   121	  const size_t tokens_per_thread = CEILDIV(numel, blockDim.x);
   122	  const size_t start_idx = threadIdx.x * tokens_per_thread;
   123	
   124	  for (int i = 0; i < num_experts; ++i) {
   125	    tokens_cnts[index(num_experts, threadIdx.x + 1, i)] = 0;
   126	  }
   127	
   128	  /**
   129	   * In the first step we compute token_cnts[thread_index + 1][expert_index],
   130	   * which counts how many tokens in the token shard of thread_index are
   131	   * assigned to expert expert_index.
   132	   */
   133	  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
   134	    ++tokens_cnts[index(num_experts, threadIdx.x + 1, topk_ids[i])];
   135	  }
   136	
   137	  __syncthreads();
   138	
   139	  // For each expert we accumulate the token counts from the different threads.
   140	  if (threadIdx.x < num_experts) {
   141	    tokens_cnts[index(num_experts, 0, threadIdx.x)] = 0;
   142	    for (int i = 1; i <= blockDim.x; ++i) {
   143	      tokens_cnts[index(num_experts, i, threadIdx.x)] +=
   144	          tokens_cnts[index(num_experts, i - 1, threadIdx.x)];
   145	    }
   146	  }
   147	
   148	  __syncthreads();
   149	
   150	  // We accumulate the token counts of all experts in thread 0.
   151	  if (threadIdx.x == 0) {
   152	    cumsum[0] = 0;
   153	    for (int i = 1; i <= num_experts; ++i) {
   154	      cumsum[i] = cumsum[i - 1] +
   155	                  CEILDIV(tokens_cnts[index(num_experts, blockDim.x, i - 1)],
   156	                          block_size) *
   157	                      block_size;
   158	    }
   159	    *total_tokens_post_pad = cumsum[num_experts];
   160	  }
   161	
   162	  __syncthreads();
   163	
   164	  /**
   165	   * For each expert, each thread processes the tokens of the corresponding
   166	   * blocks and stores the corresponding expert_id for each block.
   167	   */
   168	  if (threadIdx.x < num_experts) {
   169	    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1];
   170	         i += block_size) {
   171	      expert_ids[i / block_size] = threadIdx.x;
   172	    }
   173	  }
   174	
   175	  /**
   176	   * Each thread processes a token shard, calculating the index of each token
   177	   * after sorting by expert number. Given the example topk_ids =
   178	   * [0,1,2,1,2,3,0,3,4] and block_size = 4, then the output would be [0, 6, *,
   179	   * *, 1, 3, *, *, 2, 4, *, *, 5, 7, *, *, 8, *, *, *], where * represents a
   180	   * padding value(preset in python).
   181	   */
   182	  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
   183	    int32_t expert_id = topk_ids[i];
   184	    /** The cumsum[expert_id] stores the starting index of the tokens that the
   185	     * expert with expert_id needs to process, and
   186	     * tokens_cnts[threadIdx.x][expert_id] stores the indices of the tokens
   187	     * processed by the expert with expert_id within the current thread's token
   188	     * shard.
   189	     */
   190	    int32_t rank_post_pad =
   191	        tokens_cnts[index(num_experts, threadIdx.x, expert_id)] +
   192	        cumsum[expert_id];
   193	    sorted_token_ids[rank_post_pad] = i;
   194	    ++tokens_cnts[index(num_experts, threadIdx.x, expert_id)];
   195	  }
   196	}
   197	
   198	template <typename scalar_t, int TOPK>
   199	__global__ void moe_sum_kernel(
   200	    scalar_t* __restrict__ out,          // [..., d]
   201	    const scalar_t* __restrict__ input,  // [..., topk, d]
   202	    const int d) {
   203	  const int64_t token_idx = blockIdx.x;
   204	  for (int64_t idx = threadIdx.x; idx < d; idx += blockDim.x) {
   205	    scalar_t x = 0.0;
   206	#pragma unroll
   207	    for (int k = 0; k < TOPK; ++k) {
   208	      x += VLLM_LDG(&input[token_idx * TOPK * d + k * d + idx]);
   209	    }
   210	    out[token_idx * d + idx] = x;
   211	  }
   212	}
