   217	void moe_align_block_size(torch::Tensor topk_ids, int64_t num_experts,
   218	                          int64_t block_size, torch::Tensor sorted_token_ids,
   219	                          torch::Tensor experts_ids,
   220	                          torch::Tensor num_tokens_post_pad) {
   221	  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   222	
   223	  int device_max_shared_mem;
   224	  auto dev = topk_ids.get_device();
   225	  cudaDeviceGetAttribute(&device_max_shared_mem,
   226	                         cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
   227	
   228	  const int32_t num_thread = max((int32_t)num_experts, WARP_SIZE);
   229	  const int32_t shared_mem_i32 =
   230	      ((num_thread + 1) * num_experts + (num_experts + 1)) * sizeof(int32_t);
   231	  const int32_t shared_mem_i16 =
   232	      ((num_thread + 1) * num_experts) * sizeof(uint16_t) +
   233	      (num_experts + 1) * sizeof(int32_t);
   234	
   235	  bool use_global_memory = false;
   236	  bool use_i16 = false;  // Use uint16_t for shared memory token counts
   237	  if (shared_mem_i32 < device_max_shared_mem) {
   238	    // Do nothing in this case. We're all set to use int32_t token counts
   239	  } else if (shared_mem_i16 < device_max_shared_mem &&
   240	             topk_ids.numel() <= 65535) {
   241	    // when nelements of topk_ids is smaller than 65535 (max value of uint16),
   242	    // element value of token_cnts would also smaller than 65535,
   243	    // so we can use uint16 as dtype of token_cnts
   244	    use_i16 = true;
   245	  } else {
   246	    use_global_memory = true;
   247	  }
   248	
   249	  if (use_global_memory) {
   250	    VLLM_DISPATCH_INTEGRAL_TYPES(
   251	        topk_ids.scalar_type(), "moe_align_block_size_global_mem_kernel", [&] {
   252	          // calc needed amount of shared mem for `tokens_cnts` and `cumsum`
   253	          // tensors
   254	          const int32_t num_thread = max((int32_t)num_experts, WARP_SIZE);
   255	
   256	          auto options_int = torch::TensorOptions()
   257	                                 .dtype(torch::kInt)
   258	                                 .device(topk_ids.device());
   259	          torch::Tensor token_cnts_buffer =
   260	              torch::empty({(num_experts + 1) * num_experts}, options_int);
   261	          torch::Tensor cumsum_buffer =
   262	              torch::empty({num_experts + 1}, options_int);
   263	
   264	          auto kernel =
   265	              vllm::moe::moe_align_block_size_global_mem_kernel<scalar_t>;
   266	          kernel<<<1, num_thread, 0, stream>>>(
   267	              topk_ids.data_ptr<scalar_t>(),
   268	              sorted_token_ids.data_ptr<int32_t>(),
   269	              experts_ids.data_ptr<int32_t>(),
   270	              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   271	              topk_ids.numel(), token_cnts_buffer.data_ptr<int32_t>(),
   272	              cumsum_buffer.data_ptr<int32_t>());
   273	        });
   274	  } else if (use_i16) {
   275	    VLLM_DISPATCH_INTEGRAL_TYPES(
   276	        topk_ids.scalar_type(), "moe_align_block_size_kernel", [&] {
   277	          // set dynamic shared mem
   278	          auto kernel =
   279	              vllm::moe::moe_align_block_size_kernel<scalar_t, uint16_t>;
   280	          AT_CUDA_CHECK(VLLM_DevFuncAttribute_SET_MaxDynamicSharedMemorySize(
   281	              (void*)kernel, shared_mem_i16));
   282	          kernel<<<1, num_thread, shared_mem_i16, stream>>>(
   283	              topk_ids.data_ptr<scalar_t>(),
   284	              sorted_token_ids.data_ptr<int32_t>(),
   285	              experts_ids.data_ptr<int32_t>(),
   286	              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   287	              topk_ids.numel());
   288	        });
   289	  } else {
   290	    VLLM_DISPATCH_INTEGRAL_TYPES(
   291	        topk_ids.scalar_type(), "moe_align_block_size_kernel", [&] {
   292	          auto kernel =
   293	              vllm::moe::moe_align_block_size_kernel<scalar_t, int32_t>;
   294	          AT_CUDA_CHECK(VLLM_DevFuncAttribute_SET_MaxDynamicSharedMemorySize(
   295	              (void*)kernel, shared_mem_i32));
   296	          kernel<<<1, num_thread, shared_mem_i32, stream>>>(
   297	              topk_ids.data_ptr<scalar_t>(),
   298	              sorted_token_ids.data_ptr<int32_t>(),
   299	              experts_ids.data_ptr<int32_t>(),
   300	              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   301	              topk_ids.numel());
   302	        });
   303	  }
   304	}
