   316	  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   317	
   318	  switch (topk) {
   319	    case 2:
   320	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
