    44	   * which counts how many tokens in the token shard of thread_index are
    45	   * assigned to expert expert_index.
    46	   */
    47	  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
    48	    ++tokens_cnts[index(num_experts, threadIdx.x + 1, topk_ids[i])];
    49	  }
