   306	void moe_sum(torch::Tensor& input,   // [num_tokens, topk, hidden_size]
   307	             torch::Tensor& output)  // [num_tokens, hidden_size]
   308	{
   309	  const int hidden_size = input.size(-1);
   310	  const int num_tokens = output.numel() / hidden_size;
   311	  const int topk = input.size(1);
   312	
   313	  dim3 grid(num_tokens);
   314	  dim3 block(std::min(hidden_size, 1024));
   315	  const at::cuda::OptionalCUDAGuard device_guard(device_of(output));
   316	  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   317	
   318	  switch (topk) {
   319	    case 2:
   320	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   321	        vllm::moe::moe_sum_kernel<scalar_t, 2><<<grid, block, 0, stream>>>(
   322	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   323	            hidden_size);
   324	      });
   325	      break;
   326	
   327	    case 3:
   328	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   329	        vllm::moe::moe_sum_kernel<scalar_t, 3><<<grid, block, 0, stream>>>(
   330	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   331	            hidden_size);
   332	      });
   333	      break;
   334	
   335	    case 4:
   336	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   337	        vllm::moe::moe_sum_kernel<scalar_t, 4><<<grid, block, 0, stream>>>(
   338	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   339	            hidden_size);
   340	      });
   341	      break;
   342	
   343	    default:
   344	      at::sum_out(output, input, 1);
   345	      break;
   346	  }
   347	}
